        Map.of(
            "Random spawn bonus", "minecraft:random_spawn_bonus",
            "Random zombie-spawn bonus", "minecraft:zombie_random_spawn_bonus",
            "Leader zombie bonus", "minecraft:leader_zombie_bonus",
